mapper.select:
select r.id, r.user_id as userId, u.nickname as userName, r.object_type as objectType, r.object_id as objectId, r.message, r.status, r.result, a.nickname as resultAdminName, r.create_time as createTime, r.finish_time as finishTime from report r left join user u on r.user_id = u.id left join admin a on r.result_admin_id = a.id
and r.status = #{status} and r.object_type = #{objectType}
order by r.create_time desc

select count(*) from report r

    and r.status = #{status}
    and r.object_type = #{objectType}

mapper.update:
update report
status = #{status}, result = #{result}, result_admin_id = #{resultAdminId}, finish_time = #{finishTime},
where id = #{id}
